const { chromium } = require('playwright');
const assert = require('node:assert/strict');
const fs = require('node:fs');
(async()=>{
  const browser=await chromium.launch({channel:'chrome',headless:true});
  const page=await browser.newPage({viewport:{width:1440,height:1000},reducedMotion:'reduce'});
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.goto('http://localhost:3000/#demo/Student/Documents');
  await page.getByLabel('Upload marksheet for 2026–27').waitFor();
  const png=await page.evaluate(()=>{
    const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1100;
    const c=canvas.getContext('2d');c.fillStyle='white';c.fillRect(0,0,900,1100);
    c.fillStyle='#1e3a8a';c.fillRect(0,0,900,150);c.fillStyle='white';c.font='bold 34px Arial';c.fillText('HOSTEL OPS — TEST DOCUMENT',55,75);
    c.font='22px Arial';c.fillText('FICTIONAL SAMPLE · NOT AN OFFICIAL MARKSHEET',55,115);
    c.fillStyle='#243b53';c.font='bold 32px Arial';c.fillText('Academic result — Year 1',55,230);
    c.font='25px Arial';['Student: Aarav Sharma','College ID: STU-2026-001','Course: B.Tech · Computer Science','Academic year: 2026–27','Mathematics: 78 / 100','Programming: 84 / 100','Physics: 76 / 100','Result: PASS — sample only'].forEach((line,i)=>c.fillText(line,55,310+i*65));
    c.fillStyle='#526174';c.font='21px Arial';c.fillText('For testing the upload and manual admin review flow only.',55,980);
    return canvas.toDataURL('image/png').split(',')[1];
  });
  fs.mkdirSync('fixtures',{recursive:true});fs.mkdirSync('screenshots',{recursive:true});
  fs.writeFileSync('fixtures/sample-marksheet.png',Buffer.from(png,'base64'));
  await page.locator('#marksheet-file').setInputFiles('fixtures/sample-marksheet.png');
  await page.getByRole('button',{name:'Upload marksheet',exact:true}).click();
  await page.getByText('sample-marksheet.png',{exact:true}).waitFor();
  await page.selectOption('#role-select','Admin');
  await page.locator('.sidebar [data-page="Year Promotion"]').click();
  let row=page.getByRole('row').filter({hasText:'STU-2026-001'});
  await row.getByRole('button',{name:'Review marksheet'}).click();
  assert.equal(await page.locator('.marksheet-preview img').evaluate(img=>img.complete&&img.naturalWidth>0),true);
  await page.getByRole('button',{name:'Verify marksheet'}).click();
  assert.equal(await page.getByRole('heading',{name:'Review marksheet & eligibility'}).count(),1,'unchecked verification must not advance');
  await page.getByRole('checkbox',{name:/I have reviewed/}).check();
  await page.getByRole('button',{name:'Verify marksheet'}).click();
  await page.getByRole('heading',{name:'Promote student & release bed?'}).waitFor();
  await page.screenshot({path:'screenshots/promotion-confirmation.png'});
  await page.getByRole('button',{name:'Confirm promotion & release bed'}).click();
  assert.equal(await page.locator('.modal').count(),1,'promotion needs explicit confirmation');
  await page.getByRole('checkbox',{name:/Confirm next-year promotion/}).check();
  await page.getByRole('button',{name:'Confirm promotion & release bed'}).click();
  await page.waitForFunction(()=>!document.querySelector('.modal'));
  row=page.getByRole('row').filter({hasText:'STU-2026-001'});
  assert.match(await row.innerText(),/Year 2 of 4/);
  assert.match(await row.innerText(),/2027–28/);
  assert.match(await row.innerText(),/Awaiting allocation/);
  assert.match(await page.getByRole('row').filter({hasText:'Maple House / A-204'}).innerText(),/Empty/);
  await page.screenshot({path:'screenshots/year-promotion.png',fullPage:true});
  await page.locator('.sidebar [data-page="Dashboard"]').click();
  const availability=page.locator('.summary').filter({hasText:'Available Beds'});
  assert.equal(await availability.locator('strong').innerText(),'75');
  const maple=page.getByRole('row').filter({hasText:'Maple House'});
  assert.deepEqual(await maple.locator('td').allTextContents(),['Maple House','280','247','25','8']);
  await page.locator('.sidebar [data-page="Rooms & Beds"]').click();
  assert.match(await page.getByRole('row').filter({hasText:'Maple House / A-204'}).innerText(),/Empty/);
  await page.locator('.sidebar [data-page="Audit Logs"]').click();
  assert.match(await page.locator('main').innerText(),/Bed 02 released/);
  await page.selectOption('#role-select','Student');
  assert.match(await page.locator('.identity').innerText(),/2027–28/);
  assert.match(await page.locator('.identity').innerText(),/Not allocated/);
  await page.locator('.sidebar [data-page="My Room"]').click();
  assert.match(await page.locator('main').innerText(),/North Campus Mess/);
  assert.match(await page.locator('main').innerText(),/A-204/);
  await page.locator('.sidebar [data-page="Documents"]').click();
  assert.match(await page.locator('main').innerText(),/Archived/);
  await page.getByRole('button',{name:'View',exact:true}).click();
  assert.equal(await page.locator('.marksheet-preview img').count(),1);
  await page.getByRole('button',{name:'Close dialog'}).click();
  await page.selectOption('#role-select','Mentor');
  assert.equal(await page.locator('[data-page="Year Promotion"]').count(),0);
  assert.doesNotMatch(await page.locator('main').innerText(),/sample-marksheet|Guardian/);
  await page.selectOption('#role-select','Admin');
  await page.locator('.sidebar [data-page="Year Promotion"]').click();
  await page.setViewportSize({width:390,height:844});
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
  await page.screenshot({path:'screenshots/year-promotion-mobile.png',fullPage:true});
  assert.deepEqual(errors,[]);
  console.log('Promotion browser checks passed: local upload, preview, verification/confirmation gates, year advancement, 74→75 available beds, empty room, archived records, retained mess, admin-only navigation, mobile layout, no runtime errors.');
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1);});
